using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class IntegrationSyncRunConfiguration:IEntityTypeConfiguration<IntegrationSyncRun>{public void Configure(EntityTypeBuilder<IntegrationSyncRun>b){b.ToTable("IntegrationSyncRuns");b.HasKey(x=>x.Id);b.Property(x=>x.Error).HasMaxLength(4000);b.HasOne<ExternalIntegrationConnection>().WithMany().HasForeignKey(x=>x.ConnectionId).OnDelete(DeleteBehavior.Cascade);}}
